/**
 * The browser side of the ACP agent bridge: the wire the Go side owns, the
 * activation calls, and the WebSocket that carries one conversation.
 *
 * The names below are mirrored from `internal/acpbridge/wire.go`, where the Go
 * constants are the source; a golden fixture generated by the Go tests and asserted
 * here (phase 6) is what keeps the two from drifting, so nothing in this module may
 * rename a field on its own.
 *
 * The bridge is inert until the user activates it: this module never dials by itself,
 * `fetchAgentState` is the only call a panel may make before activation, and the
 * stream is opened only by `streamAgent`, which the panel calls when it is opened.
 */

/** Envelope kinds, mirrored from the Go constants. */
export const ENVELOPE_STATE = "state";
export const ENVELOPE_PROMPT = "prompt";
export const ENVELOPE_CANCEL = "cancel";
export const ENVELOPE_PERMISSION = "permission";
export const ENVELOPE_ELICITATION = "elicitation";
export const ENVELOPE_CONFIG = "config";
export const ENVELOPE_STATUS = "status";

/** Message roles. */
export const ROLE_USER = "user";
export const ROLE_ASSISTANT = "assistant";

/**
 * Part kinds: the first four name the session/update variant that produced them, and the
 * last two come from the prompt response — a turn's outcome.
 */
export const PART_TEXT = "text";
export const PART_THOUGHT = "thought";
export const PART_TOOL_CALL = "tool_call";
export const PART_PERMISSION = "permission";
export const PART_ELICITATION = "elicitation";
export const PART_ERROR = "error";
export const PART_STOP = "stop";

/** The user's answer to a permission card is the chosen option's id, which the request
 *  itself named; the bridge records it verbatim, so there is no translated vocabulary. */

/** The user's answer to a question, as the bridge records it. */
export const DECISION_ACCEPTED = "accepted";
export const DECISION_DECLINED = "declined";
export const DECISION_CANCELLED = "cancelled";

/** The two shapes a question can take. */
export const ELICITATION_FORM = "form";
export const ELICITATION_URL = "url";

/** The actions a browser sends back, which are the protocol's own words. */
export const ACTION_ACCEPT = "accept";
export const ACTION_DECLINE = "decline";
export const ACTION_CANCEL = "cancel";

/** Paths of the viewer's agent endpoints. */
export const AGENT_STATE_PATH = "/api/agent/state";
export const AGENT_ACTIVATE_PATH = "/api/agent/activate";
export const AGENT_DEACTIVATE_PATH = "/api/agent/deactivate";
export const AGENT_COMMAND_PATH = "/api/agent/command";
export const AGENT_STREAM_PATH = "/api/agent/stream";
export const AGENT_NEW_CHAT_PATH = "/api/agent/new-chat";

/**
 * AgentState is what the viewer reports before and after a start: whether the surface is
 * usable, what the process is doing, which session a browser would join, the command and
 * the model the project declared (so a reader can see what will run, and on which model,
 * without ever typing either), and the sentence for a failure or for an agent that could
 * not be put back on its conversation.
 */
export interface AgentState {
  activated: boolean;
  connected: boolean;
  status?: string;
  session?: string;
  command?: string[];
  /** The models the project declares, in its own order: the session may run on these, and
   *  the panel's picker offers only these. Absent means nothing was declared. */
  models?: string[];
  model?: string;
  error?: string;
}

/**
 * AgentStatusFrame is the bridge's posture pushed on the open stream: the same
 * fields the state endpoint reports, minus the thread and minus `command` (which
 * does not change while a stream is open).
 */
export interface AgentStatusFrame {
  type: string;
  activated: boolean;
  connected: boolean;
  status: string;
  sessionId?: string;
  model?: string;
  error?: string;
}

/** Permission is one request waiting for the user. */
export interface AgentPermission {
  requestId: string;
  sessionId: string;
  toolCallId?: string;
  toolKind?: string;
  title?: string;
  input?: unknown;
  /** The options the agent offered, in its own order: the card is one control per option,
   *  and the answer is the id of the one the reader chose. */
  options?: AgentPermissionOption[];
  /** Set when the answer arrives (the chosen option's id), so the card resolves in place. */
  decision?: string;
}

/** AgentPermissionOption is one choice a request offered. The kind is the protocol's hint
 *  (allow or reject, once or always) and drives the card's hierarchy, never the answer. */
export interface AgentPermissionOption {
  optionId: string;
  name: string;
  kind?: string;
}

/** Elicitation is one question the agent asks, as the bridge sends it. */
export interface AgentElicitation {
  requestId: string;
  sessionId: string;
  /** form or url. */
  mode: string;
  message: string;
  /** The requested schema, verbatim: properties, required names, title and description. */
  schema?: {
    type?: string;
    properties?: Record<string, unknown>;
    required?: string[];
    title?: string;
    description?: string;
  };
  url?: string;
  elicitationId?: string;
  /** Set when the answer arrives, so the card resolves in place. */
  decision?: string;
  /** The accepted form's values. */
  content?: Record<string, unknown>;
  /** Set by the protocol's own completion of a url question. */
  completed?: boolean;
}

/** ToolCall is one tool the agent ran. */
export interface AgentToolCall {
  id: string;
  title?: string;
  kind?: string;
  status?: string;
  input?: unknown;
  output?: unknown;
  /** What the tool itself produced, as text, when the agent sent it as content: the
   *  command's own output, which the panel shows beside the status. The raw `output`
   *  stays the protocol's record and is kept behind a disclosure. */
  content?: string;
}

/** Part is one piece of a message. */
export interface AgentPart {
  kind: string;
  text?: string;
  toolCall?: AgentToolCall;
  permission?: AgentPermission;
  elicitation?: AgentElicitation;
}

/** Message is one user or assistant turn. */
export interface AgentMessage {
  id: string;
  role: string;
  /** The bridge's own mark that this message has not been answered yet. The panel reads the
   *  turn's state from the thread's `running` instead, so the flag is no longer rendered;
   *  it is kept here because the wire carries it. */
  provisional?: boolean;
  parts: AgentPart[];
}

/** Plan is the agent's execution plan, whole or as the payload it sent. */
export interface AgentPlan {
  id?: string;
  entries?: { content: string; priority?: string; status?: string }[];
  raw?: unknown;
}

/** AgentThread is the whole state of one session, as the bridge sends it. */
export interface AgentThread {
  sessionId: string;
  /** A turn is in flight: the prompt has gone out and the agent has not finished it.
   *  The wire's one turn fact, and the reason a panel can show work rather than guess. */
  running?: boolean;
  messages: AgentMessage[];
  plan?: AgentPlan;
  commands?: { name: string; description?: string }[];
  mode?: string;
  /** The options the agent advertised for this session, kept verbatim: the bridge folds the
   *  agent's own payloads without rewriting them, so a field this module does not know about
   *  is a field the agent added. `modelOption` reads the one the panel renders. */
  config?: unknown[];
  info?: { title?: string; updatedAt?: string };
  usage?: { used: number; size: number; amount?: number; currency?: string };
}

/** AgentConfigChoice is one value an option offers, named by the agent. */
export interface AgentConfigChoice {
  value: string;
  name?: string;
  description?: string;
}

/**
 * AgentConfigOption is one configuration option the agent advertised for a session. The
 * protocol makes it a union — a select, or a boolean — and the panel renders the select; every
 * field but `id` is the agent's, and absent means the agent did not send it.
 */
export interface AgentConfigOption {
  id: string;
  name?: string;
  category?: string;
  currentValue?: string;
  type?: string;
  options?: AgentConfigChoice[];
}

/** The category an agent names its model with: the option the panel offers a control for. */
export const CONFIG_CATEGORY_MODEL = "model";

/**
 * modelOption picks the model a session is on out of what the agent advertised, or undefined
 * when it offers none — an agent without a model option gets exactly the panel that was there
 * before, because there is nothing to choose between. It is chosen by the protocol's own
 * category, not by the id the agent happens to use, and a boolean option is not a list.
 */
export function modelOption(config: unknown[] | undefined): AgentConfigOption | undefined {
  if (!config) return undefined;
  for (const raw of config) {
    const option = raw as AgentConfigOption | null;
    if (option?.category !== CONFIG_CATEGORY_MODEL) continue;
    if (option.type !== "select" || !option.options?.length) continue;
    return option;
  }
  return undefined;
}

/**
 * OfferedModels is what the picker may show: the rows, and whether the project's
 * declaration narrowed them.
 */
export interface OfferedModels {
  /** The rows to offer, in the declaration's order (the agent's own order when nothing
   *  is declared). */
  rows: AgentConfigChoice[];
  /** Whether a declaration narrowed the agent's list at all. */
  declared: boolean;
  /** Whether the declaration matched anything. False with `declared` true is the "no
   *  model this agent offers is one this project declares" case. */
  matched: boolean;
}

/**
 * offeredModels intersects the agent's choices with the models the project declares.
 *
 * `agent.models` is the list the project sanctions, in its own preference order: when it
 * is declared the picker offers exactly those the agent also advertises, and nothing else.
 * An undeclared project keeps the agent's whole list — the declaration is additive, never
 * a restriction nobody asked for.
 *
 * The model the session is on is always a row when the list is otherwise non-empty: a
 * picker that hid what is running would be lying about the one thing it exists to say. It
 * is not added when the declaration matched nothing, because then there is no picker to
 * put it in — the panel states it in the note instead.
 */
export function offeredModels(
  option: AgentConfigOption,
  declared: string[] | undefined,
  current?: string,
): OfferedModels {
  const choices = option.options ?? [];
  if (!declared || declared.length === 0) {
    return { rows: choices, declared: false, matched: true };
  }
  const byID = new Map(choices.map((choice) => [choice.value, choice]));
  const rows: AgentConfigChoice[] = [];
  for (const id of declared) {
    const choice = byID.get(id);
    // The declaration may name a model this agent does not offer (a stale id, another
    // agent): it is left out rather than shown as a row the agent would refuse.
    if (choice && !rows.some((row) => row.value === choice.value)) rows.push(choice);
  }
  if (rows.length > 0 && current && !rows.some((row) => row.value === current)) {
    rows.unshift(byID.get(current) ?? { value: current });
  }
  return { rows, declared: true, matched: rows.length > 0 };
}

/** AgentStateEnvelope is one whole-thread state, one JSON message. */
export interface AgentStateEnvelope {
  type: string;
  sessionId: string;
  thread: AgentThread;
}

/**
 * The commands a browser sends. `sessionId` names the conversation, because a command
 * travels as its own POST while the stream is a different request; omitted means "the
 * stream I am reading", which is the single-browser case.
 */
export type AgentCommand =
  | { type: typeof ENVELOPE_PROMPT; text: string; sessionId?: string }
  | { type: typeof ENVELOPE_CANCEL; sessionId?: string }
  | { type: typeof ENVELOPE_PERMISSION; requestId: string; optionId: string; sessionId?: string }
  | {
      type: typeof ENVELOPE_ELICITATION;
      requestId: string;
      action: string;
      content?: Record<string, unknown>;
      sessionId?: string;
    }
  | { type: typeof ENVELOPE_CONFIG; configId: string; value: string; sessionId?: string };

/** promptCommand builds the envelope for a user message. */
export function promptCommand(text: string, sessionId?: string): AgentCommand {
  return sessionId ? { type: ENVELOPE_PROMPT, text, sessionId } : { type: ENVELOPE_PROMPT, text };
}

/** cancelCommand asks the agent to stop the current turn. */
export function cancelCommand(sessionId?: string): AgentCommand {
  return sessionId ? { type: ENVELOPE_CANCEL, sessionId } : { type: ENVELOPE_CANCEL };
}

/** permissionCommand is the user's answer to a card: the id of the option they chose, which
 *  the request itself named. The bridge answers the agent with it verbatim. */
export function permissionCommand(
  requestId: string,
  optionId: string,
  sessionId?: string,
): AgentCommand {
  return sessionId
    ? { type: ENVELOPE_PERMISSION, requestId, optionId, sessionId }
    : { type: ENVELOPE_PERMISSION, requestId, optionId };
}

/** elicitationCommand is the user's answer to a question the agent asked. */
export function elicitationCommand(
  requestId: string,
  action: string,
  content: Record<string, unknown> | undefined,
  sessionId?: string,
): AgentCommand {
  const base: AgentCommand = { type: ENVELOPE_ELICITATION, requestId, action, content };
  return sessionId ? { ...base, sessionId } : base;
}

/**
 * configCommand sets one configuration option of a session — the model it runs on. The
 * id and the value are the agent's own, passed through verbatim: the browser never maps
 * a model name, so what the agent advertised is what it is asked for.
 */
export function configCommand(configId: string, value: string, sessionId?: string): AgentCommand {
  return sessionId
    ? { type: ENVELOPE_CONFIG, configId, value, sessionId }
    : { type: ENVELOPE_CONFIG, configId, value };
}

/** isAgentPanelKey reports whether a key event asks for the agent panel (⌘J / Ctrl+J). */
export function isAgentPanelKey(event: {
  metaKey?: boolean;
  ctrlKey?: boolean;
  key?: string;
}): boolean {
  return Boolean((event.metaKey || event.ctrlKey) && event.key?.toLowerCase() === "j");
}

/** fetchAgentState reads the bridge's posture: the one call an inert panel makes. */
export async function fetchAgentState(): Promise<AgentState> {
  return agentRequest(AGENT_STATE_PATH);
}

/**
 * activateAgent asks the viewer to start the agent the project declared in `.sdt.yaml`.
 * The request carries no body at all: the command is the project's, the viewer refuses a
 * body that names one, and that refusal is what keeps this side from ever reaching the
 * spawn path with anything of its own.
 */
export async function activateAgent(): Promise<AgentState> {
  return agentRequest(AGENT_ACTIVATE_PATH, undefined, "POST");
}

/** deactivateAgent stops the agent on purpose and returns the viewer to a stopped bridge. */
export async function deactivateAgent(): Promise<AgentState> {
  return agentRequest(AGENT_DEACTIVATE_PATH, undefined, "POST");
}

/**
 * newAgentChat ends the conversation the bridge holds and opens a fresh one: the panel's
 * one explicit way to start over. It names nothing — the conversation is the bridge's, and
 * a request does not get to choose one.
 */
export async function newAgentChat(): Promise<AgentState> {
  return agentRequest(AGENT_NEW_CHAT_PATH, undefined, "POST");
}

/** agentRequest posts to an agent endpoint and reports the viewer's message on refusal. */
async function agentRequest(path: string, body?: unknown, method = "GET"): Promise<AgentState> {
  const response = await fetch(path, {
    method,
    headers: body === undefined ? undefined : { "Content-Type": "application/json" },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (!response.ok) {
    const payload = (await response.json().catch(() => null)) as { error?: string } | null;
    throw new Error(payload?.error ?? `the viewer answered ${response.status}`);
  }
  return (await response.json()) as AgentState;
}

/** AgentStream is one open conversation. */
export interface AgentStream {
  close(): void;
}

/**
 * streamAgent opens the bridge's Server-Sent Events stream and hands every
 * whole-thread state to `onState`. There is no reconnect: `EventSource` retries a
 * dropped stream by itself, which this bridge does not want, so an error closes it and
 * reports once (`onClose`) for the panel to decide. The browser side never reassembles
 * chunks — every frame is the whole thread — so a state arriving while the caller is
 * busy is superseded by the next one rather than lost.
 */
export function streamAgent(options: {
  onState: (envelope: AgentStateEnvelope) => void;
  onStatus?: (frame: AgentStatusFrame) => void;
  onClose?: (reason: string) => void;
  url?: string;
}): AgentStream {
  const source = new EventSource(options.url ?? AGENT_STREAM_PATH);
  source.addEventListener("message", (event: MessageEvent<string>) => {
    let envelope: AgentStateEnvelope | AgentStatusFrame;
    try {
      envelope = JSON.parse(event.data) as AgentStateEnvelope | AgentStatusFrame;
    } catch {
      // A frame the wire does not define is dropped rather than fatal: the next state
      // is the whole thread, so nothing is lost by ignoring this one.
      return;
    }
    if (envelope.type === ENVELOPE_STATE) options.onState(envelope as AgentStateEnvelope);
    if (envelope.type === ENVELOPE_STATUS) options.onStatus?.(envelope as AgentStatusFrame);
  });
  source.addEventListener("error", () => {
    source.close();
    options.onClose?.("the agent stream ended");
  });
  return { close: () => source.close() };
}

/** sendAgentCommand posts one command; a refusal surfaces the viewer's own sentence. */
export async function sendAgentCommand(command: AgentCommand): Promise<void> {
  const response = await fetch(AGENT_COMMAND_PATH, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(command),
  });
  if (!response.ok) {
    const payload = (await response.json().catch(() => null)) as { error?: string } | null;
    throw new Error(payload?.error ?? `the viewer answered ${response.status}`);
  }
}
